import { DefaultTheme } from "vitepress/theme";
//#region src/client/theme-default/support/sidebar.d.ts
interface SidebarLink {
  text: string;
  link: string;
  docFooterText?: string;
  rel?: string;
  target?: string;
}
type SidebarItem = DefaultTheme.SidebarItem;
/**
 * Get the `Sidebar` from sidebar option. This method will ensure to get correct
 * sidebar config from `MultiSideBarConfig` with various path combinations such
 * as matching `guide/` and `/guide/`. If no matching config was found, it will
 * return empty array.
 */
declare function getSidebar(_sidebar: DefaultTheme.Sidebar | undefined, path: string): SidebarItem[];
/**
 * Get or generate sidebar group from the given sidebar items.
 */
declare function getSidebarGroups(sidebar: SidebarItem[]): SidebarItem[];
declare function getFlatSideBarLinks(sidebar: SidebarItem[]): SidebarLink[];
/**
 * Check if the given sidebar item contains any active link.
 */
declare function hasActiveLink(path: string, hash: string, items: SidebarItem | SidebarItem[], skipHashCheck?: boolean): boolean;
//#endregion
export { SidebarLink, getFlatSideBarLinks, getSidebar, getSidebarGroups, hasActiveLink };